import multiprocessing
import math

def calculate_primes():
    """Calculates prime numbers in an infinite loop."""
    num = 2
    while True:
        is_prime = True
        # Using math.isqrt is faster and safer for large integers than math.sqrt
        for i in range(2, math.isqrt(num) + 1):
            if num % i == 0:
                is_prime = False
                break
        # We omit printing to ensure the process remains purely CPU-bound 
        # without being bottlenecked by I/O.
        num += 1

if __name__ == '__main__':
    # Determine the number of CPU cores available
    cores = multiprocessing.cpu_count()
    print(f"Spawning {cores} processes to calculate primes indefinitely...")

    processes = []
    for _ in range(cores):
        p = multiprocessing.Process(target=calculate_primes)
        p.start()
        processes.append(p)

    try:
        # Keep the main process alive while workers run
        for p in processes:
            p.join()
    except KeyboardInterrupt:
        print("\nStopping processes...")
        for p in processes:
            p.terminate()
            p.join()
